#include <stdio.h>

int main(void) {
    int M, N;
    scanf("%d %d", &M, &N);

    int estoque[500][500];

    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%d", &estoque[i][j]);
        }
    }

    int P;
    scanf("%d", &P);

    int vendidas = 0;

    for (int k = 0; k < P; k++) {
        int I, J;
        scanf("%d %d", &I, &J);

        I--;
        J--;

        if (estoque[I][J] > 0) {
            estoque[I][J]--;
            vendidas++;
        }
    }

    printf("%d\n", vendidas);

    return 0;
}
